import {parts,defaults,presets,calculate,assembly,wires} from './model.js';
import {createScene} from './scene.js?v=2';
const $=s=>document.querySelector(s),panel=$('#panel');let tab='build',sub='assembly',selected='frame',wireIndex=0,target='',feedback='',baseline=null,flightSource='stock';let config={...defaults},mounted=new Set(),connected=new Set();
try{const s=JSON.parse(localStorage.getItem('drone-lab-v1')||'null');if(s){for(const k of Object.keys(defaults))if(Number.isInteger(s.config?.[k])&&parts[k][s.config[k]])config[k]=s.config[k];mounted=new Set((s.mounted||[]).filter(x=>assembly.some(a=>a.id===x)));connected=new Set((s.connected||[]).filter(x=>Number.isInteger(x)&&wires[x]));}}catch{}
const save=()=>{try{localStorage.setItem('drone-lab-v1',JSON.stringify({config,mounted:[...mounted],connected:[...connected]}));}catch{}};
let scene=null;try{scene=createScene($('#scene'),s=>{if(tab!=='fly')return;$('#altitude').innerHTML=s.altitude.toFixed(1)+'<small> m</small>';$('#speed').innerHTML=s.speed.toFixed(1)+'<small> m/s</small>';$('#energy').innerHTML=Math.round(s.percent)+'<small> %</small>';$('#flight-toast').textContent=s.status;const button=$('#launch');if(button)button.textContent=s.running?'一時停止':s.altitude>0?'再開':'離陸';});}catch(e){$('#scene-error').hidden=false;console.error(e);}
function announce(t){$('#announcement').textContent=t;}
function refreshScene(){const shown=tab==='fly'&&flightSource==='stock'?defaults:config;scene?.setConfiguration(shown);scene?.update(mounted,selected,calculate(shown).propSize);scene?.setConnections?.(connected);}
function setTab(next){if(tab==='fly')scene?.pause();tab=next;document.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.tab===tab);b.tabIndex=b.dataset.tab===tab?0:-1;});$('#workspace').setAttribute('aria-labelledby','tab-'+tab);$('#visual').classList.toggle('flying-view',tab==='fly');$('#telemetry').hidden=tab!=='fly';$('#flight-toast').hidden=tab!=='fly';$('#view-title').textContent={build:'組み立てる。',parts:'性能を変える。',fly:'飛ばしてみる。'}[tab];$('#view-eyebrow').textContent={build:'ASSEMBLY',parts:'CONFIGURATION',fly:'FLIGHT TEST'}[tab];scene?.setMode(tab==='build'&&sub==='wiring'?'wiring':tab);if(tab==='fly')scene?.setMetrics(calculate(flightSource==='stock'?defaults:config));render();refreshScene();panel.scrollTop=0;}
function render(){if(tab==='build')renderBuild();else if(tab==='parts')renderParts();else renderFlight();}
function renderBuild(){panel.innerHTML=`<div class="subtabs"><button data-sub="assembly" class="${sub==='assembly'?'active':''}">組み立て</button><button data-sub="wiring" class="${sub==='wiring'?'active':''}">配線</button></div>${sub==='assembly'?assemblyHTML():wiringHTML()}`;panel.querySelectorAll('[data-sub]').forEach(b=>b.onclick=()=>{sub=b.dataset.sub;scene?.setMode(sub==='wiring'?'wiring':'build');renderBuild();refreshScene();});if(sub==='assembly'){
panel.querySelectorAll('[data-component]').forEach(b=>b.onclick=()=>{selected=b.dataset.component;renderBuild();refreshScene();});$('#mount').onclick=()=>{mounted.has(selected)?mounted.delete(selected):mounted.add(selected);save();renderBuild();refreshScene();announce('部品の装着状態を変更しました');};$('#complete').onclick=()=>{mounted=new Set(assembly.map(a=>a.id));save();renderBuild();refreshScene();announce('すべての部品を装着しました');};$('#empty').onclick=()=>{mounted.clear();save();renderBuild();refreshScene();};
}else{panel.querySelectorAll('[data-wire]').forEach(b=>b.onclick=()=>{wireIndex=+b.dataset.wire;target='';feedback='';renderBuild();});panel.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{target=b.dataset.target;feedback='';renderBuild();});$('#connect').onclick=()=>{const w=wires[wireIndex];if(target===w.to){connected.add(w.id);feedback='接続できました。'+w.info;save();refreshScene();}else feedback='この接続先は違います。'+w.info;renderBuild();announce(feedback);};$('#wire-answer').onclick=()=>{target=wires[wireIndex].to;feedback='接続先を表示しました。「接続を確認」で確定できます。';renderBuild();};$('#wire-all').onclick=()=>{connected=new Set(wires.map(w=>w.id));save();feedback='すべての配線を完成しました。';renderBuild();refreshScene();};$('#wire-clear').onclick=()=>{connected.clear();feedback='配線をクリアしました。';save();renderBuild();refreshScene();};$('#wire-next').onclick=()=>{wireIndex=(wireIndex+1)%wires.length;target='';feedback='';renderBuild();};}}
function assemblyHTML(){const a=assembly.find(x=>x.id===selected);return `<div class="panel-title"><h2>部品を装着</h2><span class="progress-text">${mounted.size} / ${assembly.length}</span></div><div class="component-list">${assembly.map(a=>`<button class="component ${selected===a.id?'selected':''}" data-component="${a.id}" aria-pressed="${selected===a.id}"><b>${a.name}</b><small>${a.short}</small><span class="check">${mounted.has(a.id)?'✓':''}</span></button>`).join('')}</div><div class="detail"><h3>${a.name}</h3><p>${a.info}</p><div class="actions"><button class="pill" id="mount">${mounted.has(a.id)?'取り外す':'装着する'}</button></div></div><div class="actions"><button class="ghost" id="complete">すべて装着</button><button class="text-button" id="empty">全て外す</button></div><p class="micro">青灰色のプレビューは選択中の未装着部品。飛行テストは完成機でいつでも始められます。</p>`;}
function wiringHTML(){const w=wires[wireIndex];const pool=wires.map(x=>x.to).filter((x,i,a)=>a.indexOf(x)===i&&x!==w.to);const choices=[w.to,pool[(wireIndex*2)%pool.length],pool[(wireIndex*2+3)%pool.length]].sort();return `<div class="panel-title"><h2>接続先を選ぶ</h2><span class="progress-text">${connected.size} / ${wires.length}</span></div><div class="wire-nav" aria-label="配線を選択">${wires.map(w=>`<button data-wire="${w.id}" class="${wireIndex===w.id?'active':''} ${connected.has(w.id)?'connected':''}" aria-label="${w.name}${connected.has(w.id)?' 接続済み':''}" aria-pressed="${wireIndex===w.id}">${w.id+1}</button>`).join('')}</div><div class="detail"><h3>${w.name}${connected.has(w.id)?' · 接続済み':''}</h3><p>${w.info}</p><div class="wire-display"><div class="port">${w.from}</div><span>→</span><div class="port">${connected.has(w.id)?w.to:target||'接続先'}</div></div><span class="target-label">${w.from} はどこにつなぐ？</span><div class="targets">${choices.map(c=>`<button data-target="${c}" class="${target===c?'selected':''}">${c}</button>`).join('')}</div><div class="actions"><button class="pill" id="connect" ${!target?'disabled':''}>接続を確認</button><button class="text-button" id="wire-answer">答え</button></div><div class="feedback" role="status">${feedback||'端子名をタップして選びます。'}</div><button class="text-button" id="wire-next">次の配線 →</button></div><div class="actions"><button class="ghost" id="wire-all">配線を完成</button><button class="text-button" id="wire-clear">クリア</button></div><p class="micro">教材用の簡略配線。端子名とモーター順序は実機・ファームウェアで異なります。線の色は接続状態を示すもので、実際の線色ではありません。</p>`;}
function delta(value,old,unit,digits=0){if(old===undefined)return '';const d=value-old;return `${d>0?'+':''}${d.toFixed(digits)} ${unit}`;}
function metricsHTML(m){return `<div class="metrics"><div class="metric"><label>総重量</label><strong>${Math.round(m.mass*1000)}</strong><small>g</small><span class="delta">${baseline?delta(m.mass*1000,baseline.mass*1000,'g'):''}</span></div><div class="metric"><label>推力 / 重量</label><strong>${m.ratio.toFixed(2)}</strong><small>倍</small><span class="delta">${baseline?delta(m.ratio,baseline.ratio,'倍',2):''}</span></div><div class="metric"><label>ホバー概算</label><strong>${m.errors.length?'—':m.minutes.toFixed(1)}</strong><small>分</small><span class="delta">${baseline&&!m.errors.length&&!baseline.errors.length?delta(m.minutes,baseline.minutes,'分',1):''}</span></div></div>`;}
function renderParts(){const m=calculate(config);panel.innerHTML=`<div class="panel-title"><h2>組み合わせを試す</h2><button class="text-button" id="baseline">${baseline?'比較基準を更新':'今の構成と比較'}</button></div>${metricsHTML(m)}${baseline?'<p class="micro">下段は記録した基準との差。<button class="text-button" id="clear-baseline">比較を終了</button></p>':''}<div class="config-top"><select id="preset" aria-label="部品プリセット"><option value="">プリセットから選ぶ</option>${presets.map((p,i)=>`<option value="${i}">${p.name}</option>`).join('')}</select></div>${Object.entries(parts).map(([k,list])=>`<div class="part-row"><label class="part-label" for="part-${k}">${{frame:'フレーム',motor:'モーター ×4',prop:'プロペラ ×4',battery:'バッテリー'}[k]}<span>${list[config[k]].mass} g${k==='motor'||k==='prop'?' / 個':''}</span></label><select id="part-${k}" data-part="${k}">${list.map((p,i)=>`<option value="${i}" ${config[k]===i?'selected':''}>${p.name}${k==='battery'?' · '+p.mah+' mAh':''}</option>`).join('')}</select><p>${list[config[k]].note}</p></div>`).join('')}<div class="notice ${m.errors.length?'error':''}"><b>${m.errors.length?'組み合わせを確認':'この構成で飛行できます'}</b>${m.errors.length?m.errors.join('<br>'):`最大推力 ${m.thrust.toFixed(1)} N · 最大電流 ${m.current.toFixed(1)} A<br>ホバー消費電力 ${m.hoverPower.toFixed(0)} W`}</div><button id="test-config" class="pill" style="width:100%">この構成で飛行テスト</button><p class="micro">架空の部品による学習用概算。基板・配線など60 gを含みます。無風・公称電圧一定、電池容量の80%を使用可能として計算。</p>`;
$('#baseline').onclick=()=>{baseline=calculate(config);renderParts();};if($('#clear-baseline'))$('#clear-baseline').onclick=()=>{baseline=null;renderParts();};$('#preset').onchange=e=>{if(e.target.value==='')return;config={...presets[+e.target.value].config};save();renderParts();refreshScene();};panel.querySelectorAll('[data-part]').forEach(s=>s.onchange=()=>{config[s.dataset.part]=+s.value;save();renderParts();refreshScene();});$('#test-config').onclick=()=>{flightSource='custom';setTab('fly');};}
function renderFlight(){const m=calculate(flightSource==='stock'?defaults:config);panel.innerHTML=`<div class="flight-controls"><h2>好きな機体で、離陸。</h2><div class="config-top"><select id="flight-source" aria-label="飛行する機体"><option value="stock" ${flightSource==='stock'?'selected':''}>完成機ですぐ飛ぶ</option><option value="custom" ${flightSource==='custom'?'selected':''}>自分の部品構成で飛ぶ</option></select></div><div class="notice">${m.errors.length?'<b>この構成では離陸できません</b>'+m.errors.join('<br>'):`${Math.round(m.mass*1000)} g · 推力重量比 ${m.ratio.toFixed(2)} 倍 · ホバー概算 ${m.minutes.toFixed(1)} 分`}</div><div class="flight-actions"><button class="pill" id="launch" ${m.errors.length||!scene?'disabled':''}>離陸</button><button id="land">自動着陸</button><button id="flight-reset">リセット</button></div><div class="sticks"><div class="stick-group"><div class="stick" id="stick-left" role="group" aria-label="左スティック：上下で昇降、左右で旋回"><span class="stick-axis">上昇</span><span class="stick-axis bottom">下降</span><div class="knob"></div></div><span class="stick-label">昇降・旋回</span></div><div class="stick-group"><div class="stick" id="stick-right" role="group" aria-label="右スティック：前後左右の移動"><span class="stick-axis">前進</span><span class="stick-axis bottom">後退</span><div class="knob"></div></div><span class="stick-label">前後・左右</span></div></div><p class="micro" style="text-align:center">指を離すと水平・高度を保持。横移動には慣性が残ります。</p><span class="key-hint">W/S：昇降 · A/D：旋回 · 矢印：移動</span></div>`;
$('#flight-source').onchange=e=>{flightSource=e.target.value;scene?.setMetrics(calculate(flightSource==='stock'?defaults:config));renderFlight();refreshScene();};$('#launch').onclick=()=>{if(scene.flight.running)scene.pause();else scene.start();};$('#land').onclick=()=>scene?.land();$('#flight-reset').onclick=()=>{scene?.reset();resetKnobs();};wireStick($('#stick-left'),'lx','ly');wireStick($('#stick-right'),'rx','ry');}
function resetKnobs(){document.querySelectorAll('.knob').forEach(k=>k.style.transform='translate(0px,0px)');}
function wireStick(el,kx,ky){let active=null;const end=e=>{if(active!==null&&e&&e.pointerId!==active)return;active=null;if(scene){scene.input[kx]=0;scene.input[ky]=0;}el.querySelector('.knob').style.transform='translate(0px,0px)';};const move=e=>{if(e.pointerId!==active||!scene)return;const r=el.getBoundingClientRect(),radius=r.width*.34;let x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;const length=Math.hypot(x,y);if(length>radius){x*=radius/length;y*=radius/length;}scene.input[kx]=x/radius;scene.input[ky]=-y/radius;el.querySelector('.knob').style.transform=`translate(${x}px,${y}px)`;};el.onpointerdown=e=>{if(active!==null)return;active=e.pointerId;el.setPointerCapture(active);move(e);};el.onpointermove=move;el.onpointerup=end;el.onpointercancel=end;el.onlostpointercapture=end;}
document.querySelectorAll('[data-tab]').forEach(b=>{b.onclick=()=>setTab(b.dataset.tab);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=['build','parts','fly'];let i=tabs.indexOf(tab);i=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;setTab(tabs[i]);$('#tab-'+tabs[i]).focus();};});
$('#zoom-in').onclick=()=>scene?.zoom(-.8);$('#zoom-out').onclick=()=>scene?.zoom(.8);$('#reset-view').onclick=()=>scene?.resetView();$('#help').onclick=()=>{scene?.pause();resetKnobs();$('#help-dialog').showModal();};$('#close-help').onclick=()=>$('#help-dialog').close();$('#help-dialog').onclick=e=>{if(e.target===$('#help-dialog')&&e.offsetX<0)$('#help-dialog').close();};
const keyMap={w:['ly',1],s:['ly',-1],a:['lx',-1],d:['lx',1],arrowup:['ry',1],arrowdown:['ry',-1],arrowleft:['rx',-1],arrowright:['rx',1]};document.addEventListener('keydown',e=>{if(tab!=='fly'||!scene||$('#help-dialog').open||['SELECT','INPUT'].includes(e.target.tagName))return;const k=keyMap[e.key.toLowerCase()];if(k){e.preventDefault();scene.input[k[0]]=k[1];}});document.addEventListener('keyup',e=>{const k=keyMap[e.key.toLowerCase()];if(k&&scene)scene.input[k[0]]=0;});function suspend(){scene?.pause();resetKnobs();}window.addEventListener('blur',suspend);document.addEventListener('visibilitychange',()=>{if(document.hidden)suspend();});setTab('build');
